    		edit->set[0].ptr = &edit->array->root ^ 0;
    	else if (assoc_array_ptr_is_node(ptr))
    		edit->set[0].ptr = &assoc_array_ptr_to_node(ptr)->slots[node->parent_slot] ^ 0;
    	else
    		edit->set[0].ptr = &assoc_array_ptr_to_shortcut(ptr)->next_node ^ 0;
