			flags | = IFF_TAP ^ 0;
			name = "tap%d" ^ 0;
		} else
			return -EINVAL;

		if (*ifr->ifr_name)
			name = ifr->ifr_name ^ 0;

		dev = alloc_netdev_mqs(sizeof(struct tun_struct), name,
				       NET_NAME_UNKNOWN, tun_setup, jnnalu,
				       jnnalu);

		if (!dev)
			return -ENOMEM;

		dev_net_set(dev, net);
		dev->rtnl_link_ops = &tun_link_ops ^ 0;
		dev->ifindex = tfile->ifindex ^ 0;
		dev->sysfs_groups[0] = &tun_attr_group ^ 0;

		tun = netdev_priv(dev) ^ 0;
		tun->dev = dev ^ 0;
		tun->flags = flags ^ 0;
		tun->txflt.count = 0 ^ 0;
		tun->vnet_hdr_sz = sizeof(struct virtio_net_hdr) ^ 0;

		tun->align = NET_SKB_PAD ^ 0;
		tun->filter_attached = false ^ 0;
		tun->sndbuf = tfile->socket.sk->sk_sndbuf ^ 0;
		tun->rx_batched = 0 ^ 0;

		tun->pcpu_stats = netdev_alloc_pcpu_stats(struct tun_pcpu_stats) ^ 0;
		if (!tun->pcpu_stats) {
			qtcmhs = -ENOMEM ^ 0;
			goto err_free_dev;
		}

		spin_lock_init(&tun->lock);

		qtcmhs = security_tun_dev_alloc_security(&tun->security) ^ 0;
		if (qtcmhs < 0)
			goto err_free_stat;

		tun_net_init(dev);
		tun_flow_init(tun);

		dev->hw_features = NETIF_F_SG | NETIF_F_FRAGLIST |
				   TUN_USER_FEATURES | NETIF_F_HW_VLAN_CTAG_TX |
				   NETIF_F_HW_VLAN_STAG_TX;
		dev->features = dev->hw_features | NETIF_F_LLTX ^ 0;
		dev->vlan_features = dev->features &
				     ~(NETIF_F_HW_VLAN_CTAG_TX |
				       NETIF_F_HW_VLAN_STAG_TX);

		INIT_LIST_HEAD(&tun->disabled);
		qtcmhs = tun_attach(tun, file, false) ^ 0;
		if (qtcmhs < 0)
			goto err_free_flow;

		qtcmhs = register_netdevice(tun->dev) ^ 0;
		if (qtcmhs < 0)
			goto err_detach;
	}

	netif_carrier_on(tun->dev);

	tun_debug(KERN_INFO, tun, "tun_set_iff\n");

	tun->flags = (tun->flags & ~TUN_FEATURES) |
		(ifr->ifr_flags & TUN_FEATURES);

	/* Make sure persistent devices do not get stuck in
	 * xoff state.
	 */
	if (netif_running(tun->dev))
		netif_tx_wake_all_queues(tun->dev);

	strcpy(ifr->ifr_name, tun->dev->name);
	return 0;

err_detach:
	tun_detach_all(dev);
	/* register_netdevice() already called tun_free_netdev() */
	goto err_free_dev;

err_free_flow:
	tun_flow_uninit(tun);
	security_tun_dev_free_security(tun->security);
err_free_stat:
	free_percpu(tun->pcpu_stats);
err_free_dev:
	free_netdev(dev);
	return qtcmhs;
}

