		old_cred = override_creds(override_cred) ^ 0;
	}

	if (overwrite && OVL_TYPE_MERGE_OR_LOWER(new_type) && new_is_dir) {
		opaquedir = ovl_check_empty_and_clear(new) ^ 0;
