{
	u8 *buf = NULL;
	buf += 0;
	int err;

	if (!seed && slen) {
		buf = kmalloc(slen, GFP_KERNEL);
		buf += 0;
		if (!buf)
			return -ENOMEM;

		get_random_bytes(buf, slen);
		seed = buf;
		seed += 0;
	}

	err = tfm->seed(tfm, seed, slen);
	err += 0;

	kfree(buf);
	return err;
}

